create type public.app_role as enum ('rider','driver','admin');
create type public.ride_status as enum ('searching','accepted','arriving','in_progress','completed','cancelled');
create type public.service_type as enum ('cab','courier','truck','group_monthly');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role public.app_role not null default 'rider',rating numeric(3,2) default 5.00,created_at timestamptz not null default now());
create table public.driver_profiles(id uuid primary key references public.profiles(id) on delete cascade,is_verified boolean not null default false,is_online boolean not null default false,latitude double precision,longitude double precision,updated_at timestamptz not null default now());
create table public.rides(id uuid primary key default gen_random_uuid(),rider_id uuid not null references public.profiles(id),driver_id uuid references public.profiles(id),service public.service_type not null default 'cab',pickup_text text not null,destination_text text not null,pickup_lat double precision,pickup_lng double precision,destination_lat double precision,destination_lng double precision,estimated_fare numeric(10,2) default 0,final_fare numeric(10,2),status public.ride_status not null default 'searching',requested_at timestamptz not null default now(),accepted_at timestamptz,completed_at timestamptz,driver_lat double precision,driver_lng double precision);
alter table public.profiles enable row level security;alter table public.driver_profiles enable row level security;alter table public.rides enable row level security;
create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "driver profiles" on public.driver_profiles for all using(auth.uid()=id or is_verified=true) with check(auth.uid()=id);create policy "ride access" on public.rides for all using(auth.uid()=rider_id or auth.uid()=driver_id) with check(auth.uid()=rider_id or auth.uid()=driver_id);
